import unittest

from mdlite.inline import render_inline


class InlineTests(unittest.TestCase):
    def test_plain_text_is_escaped(self):
        self.assertEqual(render_inline("a < b & c"), "a &lt; b &amp; c")

    def test_bold(self):
        self.assertEqual(render_inline("**hi**"), "<strong>hi</strong>")

    def test_italic(self):
        self.assertEqual(render_inline("*hi*"), "<em>hi</em>")

    def test_bold_and_italic_together(self):
        self.assertEqual(
            render_inline("**a** and *b*"), "<strong>a</strong> and <em>b</em>"
        )

    def test_code_is_not_formatted_further(self):
        self.assertEqual(render_inline("`*x*`"), "<code>*x*</code>")

    def test_link(self):
        self.assertEqual(
            render_inline("[py](https://python.org)"), '<a href="https://python.org">py</a>'
        )

    def test_html_in_text_cannot_inject(self):
        self.assertEqual(render_inline("<script>"), "&lt;script&gt;")


if __name__ == "__main__":
    unittest.main()

import html
import re

from .inline import render_inline

HEADING = re.compile(r"^(#{1,6})\s+(.*)$")
RULE = re.compile(r"^(-{3,}|\*{3,})$")
BULLET = re.compile(r"^[-*+]\s+(.*)$")
NUMBERED = re.compile(r"^\d+[.)]\s+(.*)$")


def split_blocks(text):
    """Group lines into blocks. Fenced code stays whole; blank lines separate the rest."""
    blocks, current, in_fence = [], [], False
    for line in text.replace("\r\n", "\n").split("\n"):
        if in_fence:
            current.append(line)
            if line.startswith("```"):
                blocks.append(current)
                current, in_fence = [], False
        elif line.startswith("```"):
            if current:
                blocks.append(current)
            current, in_fence = [line], True
        elif not line.strip():
            if current:
                blocks.append(current)
                current = []
        else:
            current.append(line)
    if current:
        blocks.append(current)
    return blocks


def render_blocks(text):
    return "\n".join(render_block(block) for block in split_blocks(text))


def render_block(lines):
    first = lines[0]
    if first.startswith("```"):
        return render_code(lines)
    heading = HEADING.match(first)
    if heading:
        level = len(heading.group(1))
        out = f"<h{level}>{render_inline(heading.group(2))}</h{level}>"
        if len(lines) > 1:
            out += "\n" + render_block(lines[1:])
        return out
    if len(lines) == 1 and RULE.match(first):
        return "<hr>"
    if all(line.startswith(">") for line in lines):
        inner = "\n".join(line[1:].lstrip() for line in lines)
        return f"<blockquote>{render_blocks(inner)}</blockquote>"
    if all(BULLET.match(line) for line in lines):
        return render_list("ul", [BULLET.match(line).group(1) for line in lines])
    if all(NUMBERED.match(line) for line in lines):
        return render_list("ol", [NUMBERED.match(line).group(1) for line in lines])
    return "<p>" + render_inline(" ".join(line.strip() for line in lines)) + "</p>"


def render_list(tag, items):
    body = "\n".join(f"<li>{render_inline(item)}</li>" for item in items)
    return f"<{tag}>\n{body}\n</{tag}>"


def render_code(lines):
    closed = len(lines) > 1 and lines[-1].startswith("```")
    code = "\n".join(lines[1:-1] if closed else lines[1:])
    lang = lines[0][3:].strip()
    attr = f' class="language-{html.escape(lang)}"' if lang else ""
    return f"<pre><code{attr}>{code}</code></pre>"

