PAGE = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{title}</title>
<style>
body {{ font-family: Georgia, serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.6; color: #222; }}
pre {{ background: #f3f3f3; padding: 0.8rem; overflow-x: auto; border-radius: 4px; }}
code {{ font-family: Consolas, monospace; background: #f3f3f3; padding: 0 0.2rem; }}
pre code {{ padding: 0; }}
blockquote {{ border-left: 4px solid #ccc; margin-left: 0; padding-left: 1rem; color: #555; }}
</style>
</head>
<body>
{body}
</body>
</html>
"""


def render(text):
    return render_blocks(text)


def extract_title(text, default="Document"):
    for line in text.splitlines():
        if line.startswith("# "):
            return line[2:].strip()
    return default


def render_page(text, title=None):
    return PAGE.format(title=title or extract_title(text), body=render(text))

