import unittest

from mdlite.blocks import render_blocks, split_blocks


class BlockTests(unittest.TestCase):
    def test_blank_lines_separate_blocks(self):
        self.assertEqual(len(split_blocks("a\nb\n\nc")), 2)

    def test_fence_keeps_blank_lines(self):
        text = "```\none\n\ntwo\n```\nafter"
        self.assertEqual(len(split_blocks(text)), 2)

    def test_headings(self):
        self.assertEqual(render_blocks("# Title"), "<h1>Title</h1>")
        self.assertEqual(render_blocks("### Small"), "<h3>Small</h3>")

    def test_paragraph_joins_lines(self):
        self.assertEqual(render_blocks("one\ntwo"), "<p>one two</p>")

    def test_bullet_list(self):
        self.assertEqual(
            render_blocks("- a\n- b"), "<ul>\n<li>a</li>\n<li>b</li>\n</ul>"
        )

    def test_numbered_list(self):
        self.assertEqual(
            render_blocks("1. a\n2) b"), "<ol>\n<li>a</li>\n<li>b</li>\n</ol>"
        )

    def test_rule(self):
        self.assertEqual(render_blocks("---"), "<hr>")

    def test_blockquote_can_hold_blocks(self):
        self.assertEqual(
            render_blocks("> # Hi\n> there"), "<blockquote><h1>Hi</h1>\n<p>there</p></blockquote>"
        )

    def test_code_block_is_escaped(self):
        out = render_blocks("```html\n<b>x</b>\n```")
        self.assertEqual(
            out, '<pre><code class="language-html">&lt;b&gt;x&lt;/b&gt;</code></pre>'
        )

    def test_heading_followed_by_text(self):
        self.assertEqual(render_blocks("# T\ntext"), "<h1>T</h1>\n<p>text</p>")


if __name__ == "__main__":
    unittest.main()
